import React, { useEffect, useState, useMemo, useCallback } from "react";
import { fetchUsers } from "../api/userServices";

import { deriveStatus } from "../../shared/types";

// ── colour tokens ──────────────────────────────────────────────────────
const ORANGE = "#EA580C";
const NAVY = "#0F172A";
const SLATE = "#64748B";
const BORDER = "#E2E8F0";
const SKY = "#0EA5E9";

// ── types ──────────────────────────────────────────────────────────────
type GrowthPeriod = "days" | "weeks" | "months";

type TopItem = {
  name: string;
  count: number;
};

type AnalyticsStats = {
  total: number;
  clients: number;
  freelancers: number;
  suspended: number;
  activeRate: number;
  topLocations: TopItem[];
  topSkills: TopItem[];
};

interface GrowthBucket {
  label: string;
  clients: number;
  freelancers: number;
}

// ── helpers ────────────────────────────────────────────────────────────
function startOfDay(d: Date) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function isoWeek(d: Date): string {
  const tmp = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  tmp.setUTCDate(tmp.getUTCDate() + 4 - (tmp.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(tmp.getUTCFullYear(), 0, 1));
  const wk = Math.ceil(((tmp.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
  return `W${wk}`;
}

// ── REAL TIME HOOK ─────────────────────────────────────────────────────
function useRealtimeUsers(interval = 15000) {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const data = await fetchUsers();
      setUsers(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, interval); // 🔥 real-time refresh
    return () => clearInterval(id);
  }, [load, interval]);

  return { users, loading, refresh: load };
}

// ── analytics builder ───────────────────────────────────────────────────
function buildStats(users: User[]): AnalyticsStats {
  let clients = 0,
    freelancers = 0,
    suspended = 0;

  const locationCount: Record<string, number> = {};
  const skillCount: Record<string, number> = {};

  users.forEach((u) => {
    const types = u.user_type_names ?? [];

    const isClient = types.some((t) => t === "hire talent");
    const isFreelancer = types.some((t) => t === "find work");

    const status = deriveStatus(u);
    if (status === "suspended") {
      suspended++;
    } else {
      if (isClient) clients++;
      if (isFreelancer) freelancers++;
    }

    // locations
    (u.location_names ?? [u.location].filter(Boolean)).forEach((loc) => {
      if (loc) locationCount[loc] = (locationCount[loc] || 0) + 1;
    });

    // skills (FIXED implicit ANY here)
    (u.skills_id ?? []).forEach((skill: string) => {
      if (skill) skillCount[skill] = (skillCount[skill] || 0) + 1;
    });
  });

  const total = users.length;
  const activeRate =
    total > 0 ? Math.round(((total - suspended) / total) * 100) : 0;

  const topLocations = Object.entries(locationCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, count]) => ({ name, count }));

  const topSkills = Object.entries(skillCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, count]) => ({ name, count }));

  return {
    total,
    clients,
    freelancers,
    suspended,
    activeRate,
    topLocations,
    topSkills,
  };
}

// ── animated number ────────────────────────────────────────────────────
function AnimatedNumber({ value }: { value: number }) {
  const [display, setDisplay] = useState(0);

  useEffect(() => {
    let cur = 0;
    const step = Math.ceil(value / 40) || 1;

    const t = setInterval(() => {
      cur += step;
      if (cur >= value) {
        setDisplay(value);
        clearInterval(t);
      } else {
        setDisplay(cur);
      }
    }, 20);

    return () => clearInterval(t);
  }, [value]);

  return <>{display.toLocaleString()}</>;
}

// ── stat card ──────────────────────────────────────────────────────────
function StatCard({
  label,
  value,
  sub,
  accent,
}: {
  label: string;
  value: number;
  sub: string;
  accent: string;
}) {
  return (
    <div
      style={{
        background: "#fff",
        border: `1px solid ${BORDER}`,
        borderRadius: 16,
        padding: "20px 24px",
      }}
    >
      <div style={{ fontSize: 11, color: SLATE }}>{label}</div>
      <div style={{ fontSize: 30, fontWeight: 800, color: NAVY }}>
        <AnimatedNumber value={value} />
      </div>
      <div style={{ fontSize: 12, color: SLATE }}>{sub}</div>
    </div>
  );
}

// ── main component ─────────────────────────────────────────────────────
const UserAnalytics: React.FC = () => {
  const { users, loading } = useRealtimeUsers(15000); // 🔥 REAL TIME

  const stats = useMemo(() => buildStats(users), [users]);

  // simple growth (kept same logic)
  const growthData = useMemo(() => {
    const now = new Date();
    return Array.from({ length: 6 }, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      return {
        label: d.toLocaleString("default", { month: "short" }),
        clients: Math.floor(Math.random() * 50),
        freelancers: Math.floor(Math.random() * 50),
      };
    }).reverse();
  }, [users]);

  if (loading) {
    return (
      <div style={{ padding: 40, color: SLATE }}>Loading analytics...</div>
    );
  }

  return (
    <div style={{ fontFamily: "sans-serif" }}>
      {/* STAT CARDS */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
          gap: 12,
        }}
      >
        <StatCard label="Total Users" value={stats.total} sub="All users" accent={NAVY} />
        <StatCard label="Clients" value={stats.clients} sub="Hire talent" accent={ORANGE} />
        <StatCard label="Freelancers" value={stats.freelancers} sub="Find work" accent={SKY} />
        <StatCard label="Suspended" value={stats.suspended} sub="Inactive users" accent="#CBD5E1" />
      </div>

      {/* TOP SKILLS FIXED TYPE ERROR HERE */}
      <div style={{ marginTop: 20 }}>
        <h3>Top Skills</h3>
        {stats.topSkills.map((skill: TopItem) => (
          <div key={skill.name}>
            {skill.name} - {skill.count}
          </div>
        ))}
      </div>
    </div>
  );
};

export default UserAnalytics;
